class Ui5Breadcrumbs(Component):
    """### Overview Enables users to navigate between items by providing a list of links to previous steps in the user's navigation path. It helps the user to be aware of their location within the application and allows faster navigation. The last three steps can be accessed as links directly, while the remaining links prior to them are available in a drop-down menu. You can choose the type of separator to be used from a number of predefined options. ### Keyboard Handling The `ui5-breadcrumbs` provides advanced keyboard handling. - [F4], [Alt] + [Up], [Alt] + [Down], [Space], or [Enter] - If the dropdown arrow is focused - opens/closes the drop-down. - [Space],[Enter] - Activates the focused item and triggers the `item-click` event. - [Escape] - Closes the drop-down. - [Left] - If the drop-down is closed - navigates one item to the left. - [Right] - If the drop-down is closed - navigates one item to the right. - [Up] - If the drop-down is open - moves focus to the next item. - [Down] - If the drop-down is open - moves focus to the previous item. - [Home] - Navigates to the first item. - [End] - Navigates to the last item."""

    tag = "ui5-breadcrumbs"
    schema = ComponentSchema(
        tag="ui5-breadcrumbs",
        class_name="Ui5Breadcrumbs",
        summary="### Overview\nEnables users to navigate between items by providing a list of links to previous steps in the user's navigation path.\nIt helps the user to be aware of their location within the application and allows faster navigation.\n\nThe last three steps can be accessed as links directly, while the remaining links prior to them are available\nin a drop-down menu.\n\nYou can choose the type of separator to be used from a number of predefined options.\n\n### Keyboard Handling\nThe `ui5-breadcrumbs` provides advanced keyboard handling.\n\n- [F4], [Alt] + [Up], [Alt] + [Down], [Space], or [Enter] - If the dropdown arrow is focused - opens/closes the drop-down.\n- [Space],[Enter] - Activates the focused item and triggers the `item-click` event.\n- [Escape] - Closes the drop-down.\n- [Left] - If the drop-down is closed - navigates one item to the left.\n- [Right] - If the drop-down is closed - navigates one item to the right.\n- [Up] - If the drop-down is open - moves focus to the next item.\n- [Down] - If the drop-down is open - moves focus to the previous item.\n- [Home] - Navigates to the first item.\n- [End] - Navigates to the last item.",
        props=(
            PropertySchema(
                name="accessible-name", kind="string", choices=(), default=None, description="Defines the accessible name of the component."
            ),
            PropertySchema(
                name="design",
                kind="enum",
                choices=("Standard", "NoCurrentPage"),
                default="Standard",
                description='Defines the visual appearance of the last BreadcrumbsItem.\n\nThe Breadcrumbs supports two visual appearances for the last BreadcrumbsItem:\n- "Standard" - displaying the last item as "current page" (bold and without separator)\n- "NoCurrentPage" - displaying the last item as a regular BreadcrumbsItem, followed by separator',
            ),
            PropertySchema(
                name="separators",
                kind="enum",
                choices=("Slash", "BackSlash", "DoubleBackSlash", "DoubleGreaterThan", "DoubleSlash", "GreaterThan"),
                default="Slash",
                description="Determines the visual style of the separator between the breadcrumb items.",
            ),
        ),
        fields=(
            PropertySchema(
                name="accessibleName", kind="string", choices=(), default=None, description="Defines the accessible name of the component."
            ),
        ),
        events=("item-click",),
        slots=("",),
    )

    def __init__(
        self,
        *children: Child,
        key: str | None = None,
        accessible_name: str | None = None,
        design: Literal["Standard", "NoCurrentPage"] | None = None,
        separators: Literal["Slash", "BackSlash", "DoubleBackSlash", "DoubleGreaterThan", "DoubleSlash", "GreaterThan"] | None = None,
        **props: Any,
    ) -> None:
        super().__init__(
            *children,
            key=key,
            props={
                "accessible-name": accessible_name,
                "design": design,
                "separators": separators,
            },
            **props,
        )


